def handle_post(path: str):
    """(status, content_type, body_bytes) or None if this is not ours."""
    p = path.rstrip("/")
    if p != "/dash/api/recipe":
        return None
    try:
        body = json.loads(sys.stdin.buffer.read().decode("utf-8"))
    except Exception:
        return 400, "application/json", json.dumps(
            {"ok": False, "error": "body is not JSON"}).encode()
    rid = body.get("id")
    if not rid or ":" not in rid:
        return 400, "application/json", json.dumps(
            {"ok": False, "error": "id must be file:line"}).encode()
    try:
        row = save_one(rid, body)
    except KeyError as e:
        return 4
